// -----------------------------------------------------------------------------
// cxl_core_cfg.h -- CXL model parameters, generated from the **RTL macro files**
//   (never hard-code widths).  Table = cxl_core_cfg_gen.h (auto-generated by
//   tools/gen_cxl_core_cfg.py from <root>/config_*/src/*cc_constants*.svh).
//
//   Three flit profiles are kept side by side:
//     B68     = 68-byte flit      (CTL macro tag "68B")
//     HBR256  = 256-byte HBR flit (CTL macro tag "HBR")
//     PBR     = PBR flit          (CTL macro tag "PBR")
//   The **RTL profile in force** is rtl_mode(): 68B unless the build enables
//   256B/PBR.  The spec profile may use the other two width sets even when the
//   customer RTL has them disabled (they are still published in the macros).
// -----------------------------------------------------------------------------
#pragma once
#include "cxl_core_cfg_gen.h"

#include <string>

namespace cxl_tlm {

enum class CxlFlitMode { B68 = 0, HBR256 = 1, PBR = 2, COUNT = 3 };

// Channel order is frozen: cache 0..5 then mem 6..11.
enum class CxlChan {
    H2D_REQ = 0, H2D_RESP, H2D_DATA,
    D2H_REQ, D2H_RESP, D2H_DATA,
    M2S_NDR, M2S_DATA, M2S_BI_RSP,
    S2M_NDR, S2M_DATA, S2M_BI_SNP,
    COUNT
};

const char* cxl_chan_name(CxlChan c);
const char* cxl_mode_name(CxlFlitMode m);

struct CxlCoreCfg {
    const char* name = "";
    const char* rel_file = "";
    const CxlCfgEntry* prov = nullptr;   // provenance (per-parameter line numbers)
    bool complete = false;               // all required parameters present

    long long cxl_version = 0;           // CX_CXL_VERSION (2 or 3)
    long long nw = 0;                    // CX_NW (32-bit words per beat)
    long long nl = 0;                    // CX_NL (lanes)
    long long trgt_data_wd = 0;          // TRGT_DATA_WD = 32*NW
    long long nfunc = 0, nvc = 0, tag_size = 0;
    long long addr_w = 0, attr_w = 0;
    long long lbc_nw = 0, lbc_ext_aw = 0, msi_nfunc = 0;
    long long emd_size = 0;              // 0 or 32
    long long chi_maxcredits = 0;        // 2..8
    long long pclk_mode = 0;             // 3 => cxl_clk = 2*core_clk, else 1:1
    bool en_256b = false;                // CX_CXL_256B_FLIT_ENABLE
    bool en_pbr = false;                 // CX_CXL_PBR_FLIT_ENABLE

    long long width(CxlFlitMode m, CxlChan c) const;      // message size (bits, incl. Valid bit)
    long long ifnum(CxlChan c) const;                     // messages per channel interface
    long long selected_width(CxlChan c) const;            // effective (mode-resolved) size
    bool has_widths(CxlFlitMode m) const;                 // all 12 > 0
    CxlFlitMode rtl_mode() const;                         // profile in force for the customer RTL
    bool sane() const;                                    // width/credit self-consistency
    std::string describe() const;                         // one-line summary for logs/tests
};

const CxlCoreCfg& cxl_cfg_by_name(const char* name);      // not found => !complete (never silent)
int  cxl_cfg_count();
const char* cxl_cfg_name_at(int i);
const char* cxl_cfg_root();                               // env CXL_CFG_ROOT (default: ".")
std::string cxl_cfg_abs_file(const CxlCoreCfg& c);

// Named configurations used by this project (table lookup, no embedded values).
const CxlCoreCfg& cxl_cfg_sw3cxl();      // DSP (downstream port), 4 lanes, 256-bit
const CxlCoreCfg& cxl_cfg_sw3cxl_up();   // USP
const CxlCoreCfg& cxl_cfg_rpx1cxl();     // root port
const CxlCoreCfg& cxl_cfg_epx1cxl();     // endpoint reference

} // namespace cxl_tlm
